import styled from '@emotion/styled';
import { theme } from 'theme';

interface StyledSimpleBarsProps {
  $weekDelimiter?: boolean;
}

export const StyledSimpleBars = styled.div<StyledSimpleBarsProps>(
  ({ $weekDelimiter }) => ({
    flex: 1,
    borderRight: '1px solid #14141414',
    minHeight: '36px',
    ...($weekDelimiter && {
      borderRight: `1px solid ${theme.colors.charts.border.neutrals[40]}`,
    }),
  }),
);
